#define OT_LEN 8
#define OT_SIZE (1<<OT_LEN)
#define PACKET_LEN 32768
typedef struct{DISPENV disp;DRAWENV draw;uint32_t ot[OT_SIZE];char packets[PACKET_LEN];}DB;
typedef enum{STATE_TITLE,STATE_PLAY,STATE_PAUSE,STATE_DIALOGUE,STATE_GAMEOVER,STATE_ENDING,STATE_CREDITS,STATE_JOURNAL}GameState;
static DB db[2];static int active=0,font_id;static char*next_packet;static char pad_buffer[2][34];static uint16_t old_btn=0xffff;static GameState state=STATE_TITLE;
static int px=20,py=190,room=0,shards=0,timer_frames=60*60*5,health=3,anim_tick=0,walk_tick=0,facing=1,score=0,checkpoint_room=0,checkpoint_score=0,checkpoint_time=0,last_room=0,area_banner=0;
static uint8_t shard_taken[4]={0},puzzle_done[4]={0},echo_seen[4]={0};static int switch_a=0,switch_b=0,dialogue_id=0,dialogue_npc=-1,dialogue_started=0,invuln=0;static MokoGameplay gameplay;static MokoFinale finale;static MokoAdventure adventure;static MokoWorldRuntime living;
static void sfx(int p){moko_audio_sfx(p);}static void rect(int x,int y,int w,int h,int r,int g,int b){TILE*p=(TILE*)next_packet;setTile(p);setXY0(p,x,y);setWH(p,w,h);setRGB0(p,r,g,b);addPrim(db[active].ot,p);next_packet+=sizeof(TILE);}
static void init(void){ResetGraph(0);InitGeom();EnterCriticalSection();InitPAD(pad_buffer[0],34,pad_buffer[1],34);StartPAD();ChangeClearPAD(0);ExitCriticalSection();SetDefDispEnv(&db[0].disp,0,0,320,240);SetDefDrawEnv(&db[0].draw,0,240,320,240);SetDefDispEnv(&db[1].disp,0,240,320,240);SetDefDrawEnv(&db[1].draw,0,0,320,240);db[0].draw.isbg=db[1].draw.isbg=1;setRGB0(&db[0].draw,6,7,15);setRGB0(&db[1].draw,6,7,15);PutDispEnv(&db[0].disp);PutDrawEnv(&db[0].draw);SetDispMask(1);FntLoad(960,0);font_id=FntOpen(8,8,304,54,0,256);ClearOTagR(db[0].ot,OT_SIZE);ClearOTagR(db[1].ot,OT_SIZE);next_packet=db[0].packets;moko_sprite_init();moko_audio_init();gameplay_reset(&gameplay);finale_reset(&finale);adventure_reset(&adventure);world_runtime_reset(&living,0);}
static void frame(void){int rendered=active;DrawSync(0);VSync(0);DrawOTag(db[rendered].ot+OT_SIZE-1);DrawSync(0);PutDispEnv(&db[rendered^1].disp);active=rendered^1;PutDrawEnv(&db[active].draw);ClearOTagR(db[active].ot,OT_SIZE);next_packet=db[active].packets;anim_tick++;if(area_banner>0)area_banner--;}
static uint16_t buttons(void){PADTYPE*p=(PADTYPE*)pad_buffer[0];return p->stat==0?p->btn:0xffff;}static int pressed(uint16_t n,uint16_t k){return !(n&k)&&(old_btn&k);}static int hit(int a,int b,int c,int d,int e,int f,int g,int h){return a<e+g&&a+c>e&&b<f+h&&b+d>f;}static void say(int id){dialogue_id=id;dialogue_npc=-1;dialogue_started=0;state=STATE_DIALOGUE;}
static void reset_game(void){int i;px=20;py=190;room=0;last_room=0;shards=0;health=3;score=0;timer_frames=60*60*5;switch_a=switch_b=0;invuln=0;area_banner=100;checkpoint_room=0;checkpoint_score=0;checkpoint_time=timer_frames;gameplay_reset(&gameplay);finale_reset(&finale);adventure_reset(&adventure);world_runtime_reset(&living,0);for(i=0;i<4;i++){shard_taken[i]=0;puzzle_done[i]=0;echo_seen[i]=0;}moko_audio_set_room(0);sfx(0x1200);say(1);}
static void draw_moko(void){int i;if(gameplay.dash_timer>0)for(i=1;i<4;i++)rect(px-(facing?i*5:-i*5),py+5,8,10,25+i*10,70+i*15,95+i*20);moko_sprite_draw(px,py,facing,walk_tick,invuln,anim_tick,db[active].ot,&next_packet);}static void draw_shard(int x,int y){int p=(anim_tick/8)&3;rect(x-2-p,y-5-p,13+p*2,24+p*2,25,75,90);rect(x,y,9,14,80,215,245);rect(x+2,y-4,5,4,190,250,255);rect(x+3,y+3,3,6,230,255,255);}static int hx(void){return 40+((anim_tick*2)%230);}static int hy(void){return 78+(anim_tick%115);}static int pulse_x(int seed){return 25+((anim_tick*(2+seed)+seed*71)%270);}
static void echo_art(void){int p=2+((anim_tick/10)&3);if(room<4&&!echo_seen[room]){int ex=55+room*38,ey=112+room*17;rect(ex-p,ey-p,12+p*2,12+p*2,22,55,75);rect(ex,ey,12,12,95,175,205);rect(ex+4,ey+3,4,6,205,240,245);}}
static void station_art(void){int i;rect(0,58,320,164,13,18,35);rect(0,194,320,28,28,34,52);rect(0,218,320,4,95,84,70);for(i=0;i<5;i++){int x=18+i*68;rect(x,72,48,34,20,35,62);rect(x+3,75,42,28,32,48,78);}rect(92,114,136,7,65,76,100);rect(112,180,18,28,85,100,150);rect(151,124,18,18,205,190,130);}
static void street_art(void){int i;rect(0,58,320,164,27,13,35);rect(0,202,320,20,42,24,45);for(i=0;i<6;i++){int x=i*58-8,h=48+(i%3)*14;rect(x,202-h,48,h,48,24,55);}rect(145,176,18,46,170,45,65);rect(220,195,18,27,170,45,65);rect(70,190,14,14,switch_a?60:150,switch_a?210:60,70);rect(270,110,14,14,switch_b?60:150,switch_b?210:60,70);rect(hx(),142,16,8,220,70,80);if(!puzzle_done[1]){rect(pulse_x(1),124,12,5,225,75,105);rect(pulse_x(2),166,10,5,195,55,95);}}
static void house_art(void){int i;rect(0,58,320,164,11,29,29);rect(0,205,320,17,37,49,43);for(i=0;i<4;i++){int x=28+i*76;rect(x,94,45,58,24,51,48);rect(x+5,99,35,48,42,75,67);}rect(125,95,12,127,45,150,115);rect(260,130,12,92,45,150,115);rect(190,hy(),8,18,170,220,190);if(!puzzle_done[2]){rect(156,62,4,70,160,205,180);rect(226,152,4,58,160,205,180);}}
static void clockworks_art(void){int i;rect(0,58,320,164,31,22,10);rect(0,210,320,12,62,43,20);for(i=0;i<7;i++){int x=12+i*48,y=75+(i%2)*34;rect(x,y,30,30,72,49,22);rect(x+5,y+5,20,20,154,101,31);}rect(90,190,45,6,215,130,35);rect(200,110,45,6,215,130,35);rect(hx(),160,20,6,240,145,35);rect(178,136,5,74,gameplay.dash_timer?70:235,gameplay.dash_timer?210:70,55);rect(238,62,5,94,gameplay.dash_timer?70:235,gameplay.dash_timer?210:70,55);}
static void chamber_art(void){int i,sx,p;rect(0,58,320,164,27,7,12);rect(0,210,320,12,52,19,25);rect(104,70,112,92,43,19,28);rect(128,82,64,64,90,55,65);for(i=0;i<4;i++){sx=110+i*28;if(finale.socket[i]){p=(anim_tick/9+i)&3;rect(sx-2-p,153-p,16+p*2,16+p*2,22,90,105);rect(sx,155,12,12,90,235,250);}else rect(sx-2,153,16,16,55,30,40);}if(finale_hazard_active(&finale)){rect(finale_sweep_x(&finale),68,3,140,235,55,75);if(finale.phase==FINALE_STABILIZE)rect(28,finale_sweep_y(&finale),264,3,70,170,230);}if(finale.phase==FINALE_STABILIZE){rect(82,186,156,8,35,25,35);rect(84,188,(finale.stability*152)/100,4,75,220,235);}}
static void world_event_art(void){int i;for(i=0;i<MOKO_WORLD_EVENT_COUNT;i++){const MokoWorldEventDef*d=adventure_event(&adventure,i);int p;if(!d||d->room!=room||adventure.world.collected[i]||adventure_near_event(&adventure,room,d->x,d->y,1)!=i)continue;p=2+((anim_tick/8+i)&3);if(d->kind==WORLD_EVENT_PICKUP){rect(d->x-3,d->y-3,10,10,35,95,105);rect(d->x,d->y,5,5,110,235,230);}else if(d->kind==WORLD_EVENT_SECRET){rect(d->x-p,d->y-p,8+p*2,8+p*2,75,35,95);rect(d->x,d->y,7,7,220,90,230);}else{rect(d->x-2,d->y-2,9,9,95,80,35);rect(d->x,d->y,5,5,245,205,90);}}}
static void living_art(void){int i;for(i=0;i<ambient_count(&living.ambient);i++){const MokoAmbientParticle*p=ambient_particle(&living.ambient,i);if(!p)continue;if(p->kind==AMBIENT_RAIN)rect(p->x,p->y,1,5,90,120,170);else if(p->kind==AMBIENT_SPARK)rect(p->x,p->y,2,2,235,160,55);else if(p->kind==AMBIENT_GEAR)rect(p->x,p->y,4,4,145,100,40);else rect(p->x,p->y,2,2,75,100,115);}for(i=0;i<MOKO_NPC_COUNT;i++){const MokoNpcDef*n=npc_get(i);int pending;if(!n||n->room!=room)continue;if(n->kind==NPC_CAT){rect(n->x-5,n->y-9,11,7,75,95,115);rect(n->x+4,n->y-7,5,5,185,160,135);rect(n->x+5,n->y-10,2,3,185,160,135);rect(n->x+8,n->y-10,2,3,185,160,135);}else{rect(n->x-4,n->y-14,10,14,55,85,105);rect(n->x-2,n->y-19,7,7,190,165,140);}pending=adventure_npc_delivery_required(i)?!adventure_npc_delivered(&adventure,i):!quests_is_clear(&adventure.quests,n->quest);if(!adventure_npc_met(&adventure,i))rect(n->x-1,n->y-27,4,5,235,205,75);else if(pending)rect(n->x-1,n->y-27,4,4,75,210,235);if(n->kind!=NPC_CAT&&((anim_tick/20)+i)&1)rect(n->x+7,n->y-10,2,5,110,205,220);}for(i=0;i<MOKO_ENEMY_COUNT;i++){const MokoEnemy*e=enemies_get(&living.enemies,i);if(!e||!e->active||e->room!=room)continue;if(e->kind==ENEMY_GEARLING){rect(e->x-5,e->y-7,12,12,155,95,35);rect(e->x-2,e->y-4,6,6,235,170,55);}else if(e->kind==ENEMY_SHADOW){rect(e->x-5,e->y-13,11,16,45,30,65);rect(e->x-2,e->y-10,2,2,210,80,220);}else{rect(e->x-6,e->y-9,13,10,120,45,65);rect(e->x+(e->vx>0?5:-3),e->y-7,2,2,245,210,95);}}}
static void room_art(void){int i;if(room==0)station_art();else if(room==1)street_art();else if(room==2)house_art();else if(room==3)clockworks_art();else chamber_art();for(i=0;i<7;i++)rect((i*47+anim_tick/2)%320,68+((i*29+anim_tick/4)%132),1,1,70,75,100);living_art();world_event_art();echo_art();if(room<4&&!shard_taken[room]&&puzzle_done[room])draw_shard(250-room*35,90+room*28);draw_moko();}
static void collect_shard(uint16_t n){int sx,sy;if(room>=4||shard_taken[room]||!puzzle_done[room]||!pressed(n,PAD_CROSS))return;sx=250-room*35;sy=90+room*28;if(hit(px,py,12,18,sx-8,sy-9,25,31)){shard_taken[room]=1;shards++;adventure_story_progress(&adventure,16,1);gameplay_reward(&gameplay,250);gameplay_record_shard(&gameplay);score+=250+gameplay_score_bonus(&gameplay);checkpoint_room=room;checkpoint_score=score;checkpoint_time=timer_frames;sfx(0x2400);say(8);}}
static void memory_echo(uint16_t n){int ex,ey;if(room>=4||echo_seen[room]||!pressed(n,PAD_CROSS))return;ex=55+room*38;ey=112+room*17;if(hit(px,py,12,18,ex-10,ey-10,32,32)){echo_seen[room]=1;adventure_story_progress(&adventure,17,1);gameplay_reward(&gameplay,75);gameplay_record_echo(&gameplay);score+=75+gameplay_score_bonus(&gameplay);sfx(0x2000);say(10+room);}}
static int finale_interact(void){int i,sx;if(room!=4||shards<4)return 0;finale_begin(&finale,shards);if(finale.phase!=FINALE_RESTORE)return 0;for(i=0;i<4;i++){sx=110+i*28;if(!finale.socket[i]&&hit(px,py,12,18,sx-10,145,32,34)&&finale_activate_socket(&finale,i,shards)){adventure_story_progress(&adventure,20,1);gameplay_reward(&gameplay,125);score+=125+gameplay_score_bonus(&gameplay);sfx(0x2000+i*0x300);if(finale.phase==FINALE_STABILIZE)say(15);return 1;}}return 0;}
static int npc_interact(void){int id=world_runtime_near_npc(&living,room,px,py,24);const MokoNpcDef*n;if(id<0)return 0;n=npc_get(id);if(!n)return 0;dialogue_started=adventure_npc_talk(&adventure,id);if(dialogue_started==2){int reward=adventure_npc_reward(&adventure);score+=reward;gameplay_reward(&gameplay,reward/4);sfx(0x2600);}else sfx(dialogue_started?0x1900:0x0d00);dialogue_npc=id;dialogue_id=100;state=STATE_DIALOGUE;return 1;}
static void interact(uint16_t n){int reward;if(!pressed(n,PAD_CROSS))return;memory_echo(n);if(state!=STATE_PLAY)return;if(finale_interact())return;if(npc_interact())return;reward=adventure_interact(&adventure,room,px,py);if(reward){score+=reward>1?reward:25;sfx(0x2200);return;}if(room==0&&hit(px,py,12,18,105,170,32,45)&&!puzzle_done[0]){puzzle_done[0]=1;adventure_story_clear(&adventure,1);gameplay_reward(&gameplay,100);score+=100;sfx(0x2000);say(2);}if(room==1){if(hit(px,py,12,18,65,180,28,30)&&!switch_a){switch_a=1;adventure_story_progress(&adventure,4,1);}if(hit(px,py,12,18,265,100,28,30)&&!switch_b){switch_b=1;adventure_story_progress(&adventure,4,1);}if(switch_a&&switch_b&&!puzzle_done[1]){puzzle_done[1]=1;gameplay_reward(&gameplay,150);score+=150;sfx(0x2200);say(3);}}if(room==2&&hit(px,py,12,18,180,70,55,110)&&!puzzle_done[2]){puzzle_done[2]=1;adventure_story_clear(&adventure,8);gameplay_reward(&gameplay,175);score+=175;sfx(0x2300);say(4);}if(room==3&&gameplay.dash_timer>0&&hit(px,py,12,18,145,75,50,45)&&!puzzle_done[3]){puzzle_done[3]=1;adventure_story_clear(&adventure,12);gameplay_reward(&gameplay,200);score+=200;sfx(0x2600);say(5);}collect_shard(n);}
static void hurt(void){if(invuln||gameplay.dash_timer>0)return;health--;score=score>=25?score-25:0;invuln=60;gameplay_break_combo(&gameplay);sfx(0x0700);px=30;py=190;if(health<=0){gameplay_record_death(&gameplay);state=STATE_GAMEOVER;}}
static void update_play(uint16_t n){int ox=px,oy=py,m=0,spd;last_room=room;if(pressed(n,PAD_SELECT)){adventure_journal_sync(&adventure);state=STATE_JOURNAL;return;}if(pressed(n,PAD_R1)&&gameplay_try_dash(&gameplay)){adventure_dash(&adventure);sfx(0x2b00);}spd=gameplay_move_speed(&gameplay);if(!(n&PAD_LEFT)){px-=spd;facing=0;m=1;}if(!(n&PAD_RIGHT)){px+=spd;facing=1;m=1;}if(!(n&PAD_UP)){py-=spd;m=1;}if(!(n&PAD_DOWN)){py+=spd;m=1;}if(gameplay.dash_timer>0&&!m){px+=facing?spd:-spd;m=1;}if(m)walk_tick+=gameplay.dash_timer>0?2:1;else walk_tick=0;gameplay_tick(&gameplay,m);if(px<0){if(room>0){room--;px=306;sfx(0x0d00);}else px=0;}if(px>308){if(room<4&&shard_taken[room]){room++;px=2;sfx(0x0d00);}else px=308;}if(room!=last_room){area_banner=90;gameplay.room_time=0;moko_audio_set_room(room);if(room==4)finale_begin(&finale,shards);}if(py<62)py=62;if(py>204)py=204;if(room==1&&(hit(px,py,12,18,145,176,18,46)||hit(px,py,12,18,220,195,18,27))){px=ox;py=oy;}if(room==2&&(hit(px,py,12,18,125,95,12,127)||hit(px,py,12,18,260,130,12,92))){px=ox;py=oy;}if(room==2&&!puzzle_done[2]&&gameplay.dash_timer<=0&&(hit(px,py,12,18,156,62,4,70)||hit(px,py,12,18,226,152,4,58))){px=ox;py=oy;}if(room==3&&gameplay.dash_timer<=0&&(hit(px,py,12,18,178,136,5,74)||hit(px,py,12,18,238,62,5,94))){px=ox;py=oy;}world_runtime_tick(&living,room,px,py);if(gameplay.dash_timer>0&&world_runtime_dash(&living,room,px,py,facing?1:-1)>=0){score+=50;gameplay_reward(&gameplay,20);sfx(0x2600);}interact(n);if(state!=STATE_PLAY)return;if(invuln>0)invuln--;if(world_runtime_touch_enemy(&living,room,px,py)>=0)hurt();if(room==1&&(hit(px,py,12,18,hx(),142,16,8)||(!puzzle_done[1]&&(hit(px,py,12,18,pulse_x(1),124,12,5)||hit(px,py,12,18,pulse_x(2),166,10,5)))))hurt();if(room==2&&hit(px,py,12,18,190,hy(),8,18))hurt();if(room==3&&(hit(px,py,12,18,90,184,45,18)||hit(px,py,12,18,hx(),160,20,6)))hurt();if(room==4){finale_tick(&finale,gameplay.dash_timer>0);if(finale_hazard_active(&finale)&&(hit(px,py,12,18,finale_sweep_x(&finale),68,3,140)||(finale.phase==FINALE_STABILIZE&&hit(px,py,12,18,28,finale_sweep_y(&finale),264,3))))hurt();if(finale_complete(&finale)){adventure_story_clear(&adventure,21);score+=finale_score_bonus(&finale)+timer_frames/60;sfx(0x2f00);state=STATE_ENDING;}}adventure_tick(&adventure,room,shards,gameplay.echoes,gameplay.combo,health,gameplay.focus);moko_audio_tick();if(pressed(n,PAD_START))state=STATE_PAUSE;if(timer_frames>0)timer_frames--;else{gameplay_record_death(&gameplay);state=STATE_GAMEOVER;}}
static void hud(void){static const char*n[]={"SILENT STATION","BACKWARD STREET","HOUSE WITHOUT MORNING","CLOCKWORKS","CLOCK CHAMBER"};int s=timer_frames/60,near=adventure_near_event(&adventure,room,px,py,24),ni=npc_near(room,px,py,24);FntPrint(font_id,"%02d:%02d S%d/4 HP%d SCORE%d FOCUS%d\n%s R1:DASH SELECT:JOURNAL EV%d%%",s/60,s%60,shards,health,score,gameplay.focus,n[room],adventure_completion(&adventure));if(ni>=0){const MokoNpcDef*p=npc_get(ni);if(p)FntPrint(font_id,"\nCROSS - TALK: %s",p->name);}else if(near>=0){const MokoWorldEventDef*d=adventure_event(&adventure,near);if(d)FntPrint(font_id,"\nCROSS - %s",d->label);}if(adventure.notice_timer>0)FntPrint(font_id,"\nEVENT CLEAR: %s",adventure_notice(&adventure));else if(adventure.challenge_notice_timer>0){int q=adventure.challenge_notice_quest;FntPrint(font_id,"\nCHALLENGE: %s %d/%d",adventure_challenge_notice(&adventure),adventure.quests.progress[q],adventure.quests.target[q]);}FntFlush(font_id);}
static void draw_journal(void){MokoJournal*j=&adventure.journal;rect(0,0,320,240,5,8,18);rect(10,10,300,30,15,25,42);FntPrint(font_id,"MOKO MEMORY JOURNAL   EV %d%% AP %d\n",adventure_completion(&adventure),adventure.quests.ap);if(j->tab==0){int id=journal_quest(j),p=journal_quest_progress(j,&adventure.quests),t=journal_quest_target(j,&adventure.quests);FntPrint(font_id,"\n[ QUESTS ]   ITEMS\n\n%s\n%s\n\nPROGRESS %d/%d   %s\n\nUP/DOWN - NEXT EVENT\nLEFT/RIGHT - ITEMS\nSELECT - CLOSE",journal_quest_name(j),journal_quest_hint(j),p,t,adventure.quests.state[id]==QUEST_CLEAR?"CLEAR":"ACTIVE");}else{int id=journal_item(j);FntPrint(font_id,"\n  QUESTS   [ ITEMS ]\n\n%s\nQUANTITY %d\n\nCOLLECTED MEMORY OBJECT\nSome objects unlock hidden events.\n\nUP/DOWN - NEXT ITEM\nLEFT/RIGHT - QUESTS\nSELECT - CLOSE",id>=0?journal_item_name(j):"NO ITEMS YET",id>=0?journal_item_count(j,&adventure.inventory):0);}FntFlush(font_id);}
static void update_journal(uint16_t n){if(pressed(n,PAD_SELECT)||pressed(n,PAD_CIRCLE)){state=STATE_PLAY;return;}if(pressed(n,PAD_LEFT)||pressed(n,PAD_RIGHT)){adventure_journal_tab(&adventure);sfx(0x0d00);}if(pressed(n,PAD_UP))adventure_journal_move(&adventure,-1);if(pressed(n,PAD_DOWN))adventure_journal_move(&adventure,1);}
static void dialogue(void){room_art();rect(12,158,296,70,8,8,18);if(dialogue_npc>=0){const MokoNpcDef*n=npc_get(dialogue_npc);if(n){int delivered=adventure_npc_delivery_required(dialogue_npc)?adventure_npc_delivered(&adventure,dialogue_npc):quests_is_clear(&adventure.quests,n->quest);FntPrint(font_id,"%s:\n%s",n->name,delivered?n->line_after:n->line_before);if(dialogue_started==1)FntPrint(font_id,"\nNEW EVENT: %s",quests_name(n->quest));else if(dialogue_started==2)FntPrint(font_id,"\nDELIVERY COMPLETE +%d",adventure_npc_reward(&adventure));}}else if(dialogue_id==1)FntPrint(font_id,"The hour was broken. Find what you forgot.\nR1 - MEMORY DASH");else if(dialogue_id==8)FntPrint(font_id,"MEMORY SHARD RECOVERED. CHECKPOINT SAVED.");else if(dialogue_id>=10&&dialogue_id<=13)FntPrint(font_id,"A MEMORY ECHO RETURNS.\nSomething forgotten is becoming clear.");else if(dialogue_id==15)FntPrint(font_id,"THE CLOCK IS AWAKE.\nDash through the fracture. Hold the hour together.");else FntPrint(font_id,"A memory has shifted the Lost Hour.");FntPrint(font_id,"\nCROSS - continue");FntFlush(font_id);}
int main(void){init();for(;;){uint16_t n=buttons();if(state==STATE_TITLE){rect(0,0,320,240,7,8,20);FntPrint(font_id,"\n\n      M O K O\n   THE LOST HOUR\n\n START - BEGIN\n Find four shards. Remember why.");FntFlush(font_id);if(pressed(n,PAD_START)||pressed(n,PAD_CROSS))reset_game();}else if(state==STATE_PLAY){update_play(n);room_art();hud();}else if(state==STATE_JOURNAL){update_journal(n);draw_journal();}else if(state==STATE_DIALOGUE){dialogue();if(pressed(n,PAD_CROSS)){dialogue_npc=-1;dialogue_started=0;state=STATE_PLAY;}}else if(state==STATE_PAUSE){room_art();FntPrint(font_id,"PAUSED SCORE %d FOCUS %d\nBEST COMBO x%d EVENTS %d%%\nSTART - RESUME",score,gameplay.focus,gameplay.best_combo,adventure_completion(&adventure));FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_PLAY;}else if(state==STATE_GAMEOVER){rect(0,0,320,240,24,5,10);FntPrint(font_id,"\n THE HOUR IS LOST\n SCORE %d BEST x%d\n\nCROSS - CHECKPOINT\nSTART - NEW GAME",score,gameplay.best_combo);FntFlush(font_id);if(pressed(n,PAD_CROSS)){room=checkpoint_room;px=20;py=190;health=3;score=checkpoint_score;timer_frames=checkpoint_time>1800?checkpoint_time:1800;invuln=90;state=STATE_PLAY;}if(pressed(n,PAD_START))reset_game();}else if(state==STATE_ENDING){rect(0,0,320,240,10,20,28);FntPrint(font_id,"\n THE LOST HOUR RETURNS\n\nMoko remembers. Time can move again.\n\nSCORE %d EVENTS %d%%\n\nCROSS - CREDITS",score,adventure_completion(&adventure));FntFlush(font_id);if(pressed(n,PAD_CROSS))state=STATE_CREDITS;}else{rect(0,0,320,240,4,4,10);FntPrint(font_id,"\n\n MOKO: THE LOST HOUR\n\n A game by ADSSS93\n Built for the original PlayStation\n\n Thank you for remembering.\n\n START - TITLE");FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_TITLE;}old_btn=n;frame();}return 0;}
